"use client";
import { useState } from "react";
import { EosPillFilters } from "@/components/application/eos/pill-filters";

const ITEMS = [
  { value: "all", label: "All routines" },
  { value: "finance", label: "Finance" },
  { value: "sales", label: "Sales" },
  { value: "support", label: "Support" },
  { value: "engineering", label: "Engineering" },
  { value: "hiring", label: "Hiring" },
  { value: "marketing", label: "Marketing" },
];

/** One choice at a time; arrow keys move it, and the row scrolls sideways when it runs out of room. */
export default function EosPillFiltersDemo() {
  const [value, setValue] = useState("all");
  const chosen = ITEMS.find((item) => item.value === value)?.label ?? "";
  return (
    <div style={{ display: "grid", gap: 16, width: "100%", maxWidth: 720, margin: "0 auto" }}>
      <EosPillFilters items={ITEMS} value={value} onChange={setValue} label="Filter routines" />
      <p style={{ margin: 0, fontSize: 15, color: "#62615D" }}>Showing {chosen.toLowerCase()}</p>
    </div>
  );
}

