"use client";
/**
 * EosPillFilters: a single-select row of pills, black when chosen and white and outlined otherwise. One pill is in
 * the tab order (roving tabindex); arrow keys, Home and End move the choice. On a narrow screen the row scrolls
 * sideways and keeps the focused pill in view.
 *
 * The black is one shared indicator that slides to the chosen pill (motion.ts), under the labels, while the chosen
 * label's light ink fades in over its dark one. A pill lifts a little on hover, its shadow fading in, and settles on
 * press. Before the indicator is placed (on the server, before hydration) the chosen pill paints itself.
 */
import { useEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from "react";
import { EosIndicator, useEosIndicator } from "./motion";
import { cx, rovingIndex, useControlled } from "./shared";
import { EosScope, useEosTheme } from "./theme";

export interface EosPillFilterItem {
  value: string;
  label: string;
  /** Shown after the label, e.g. how many routines a category holds. */
  count?: number;
}

const CSS = `
.eos-pills{position:relative;isolation:isolate;display:flex;contain:inline-size;gap:10px;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none;padding:4px 3px 10px;margin:-4px -3px -10px;scroll-padding-inline:24px;font-family:var(--eos-font-body)}
.eos-pills::-webkit-scrollbar{display:none}
.eos-pills[data-fade=end]{-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 56px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 56px),transparent)}
.eos-pills[data-fade=both]{-webkit-mask-image:linear-gradient(90deg,transparent,#000 40px,#000 calc(100% - 56px),transparent);mask-image:linear-gradient(90deg,transparent,#000 40px,#000 calc(100% - 56px),transparent)}
.eos-pills[data-fade=start]{-webkit-mask-image:linear-gradient(90deg,transparent,#000 40px);mask-image:linear-gradient(90deg,transparent,#000 40px)}
.eos-pill{position:relative;flex:none;display:inline-flex;align-items:center;height:var(--eos-pill-h);padding:0 var(--eos-pill-pad);border:0;border-radius:var(--eos-radius-pill);background:transparent;color:var(--eos-pill-text);font:inherit;font-size:var(--eos-pill-font);font-weight:450;letter-spacing:-.005em;white-space:nowrap;cursor:pointer;-webkit-tap-highlight-color:transparent}
.eos-pill::before,.eos-pill::after{content:"";position:absolute;inset:0;box-sizing:border-box;border-radius:inherit;pointer-events:none;transition:transform var(--eos-dur-hover) var(--eos-ease),opacity var(--eos-dur-hover) var(--eos-ease)}
.eos-pill::before{border:1px solid var(--eos-pill-border);background:var(--eos-pill);-webkit-backdrop-filter:blur(var(--eos-card-blur));backdrop-filter:blur(var(--eos-card-blur))}
.eos-pill::after{box-shadow:var(--eos-lift-shadow-sm);opacity:0}
.eos-pill-in{position:relative;z-index:1;display:inline-flex;align-items:center;gap:8px;transition:transform var(--eos-dur-hover) var(--eos-ease)}
.eos-pill-t{position:relative}
.eos-pill-t::after{content:attr(data-text);content:attr(data-text) / "";position:absolute;left:0;top:0;color:var(--eos-pill-active-text);opacity:0;pointer-events:none;transition:opacity var(--eos-dur-indicator) var(--eos-ease)}
.eos-pill[aria-checked=true] .eos-pill-t::after{opacity:1}
.eos-pills:not([data-eos-ind=on])>.eos-pill[aria-checked=true]::before{border-color:var(--eos-pill-active);background:var(--eos-pill-active)}
.eos-pills>.eos-ind{--eos-ind-fill:var(--eos-pill-active);transition:transform var(--eos-dur-press) var(--eos-ease)}
.eos-pill:active::before,.eos-pill:active::after,.eos-pill:active .eos-pill-in{transform:scale(var(--eos-press));transition-duration:var(--eos-dur-press)}
.eos-pills:has(>.eos-pill[aria-checked=true]:active)>.eos-ind{transform:scale(var(--eos-press))}
@media (hover:hover){
  .eos-pill:not([aria-checked=true]):hover::before,.eos-pill:not([aria-checked=true]):hover::after,.eos-pill:not([aria-checked=true]):hover .eos-pill-in{transform:translateY(var(--eos-lift-sm))}
  .eos-pill:not([aria-checked=true]):hover::after{opacity:1}
  .eos-pill:not([aria-checked=true]):hover:active::before,.eos-pill:not([aria-checked=true]):hover:active::after,.eos-pill:not([aria-checked=true]):hover:active .eos-pill-in{transform:translateY(var(--eos-lift-sm)) scale(var(--eos-press))}
}
.eos-pill:focus-visible{outline:2px solid var(--eos-focus);outline-offset:2px}
.eos-pill-count{font-variant-numeric:tabular-nums;font-weight:400}
`;

const SIZES = { md: { h: 36, pad: 16, font: 14.5 }, lg: { h: 44, pad: 20, font: 16 } } as const;

export interface EosPillFiltersProps {
  items?: readonly EosPillFilterItem[];
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** The group's accessible name. */
  label?: string;
  size?: keyof typeof SIZES;
  className?: string;
  style?: CSSProperties;
}

export const EOS_PILL_DEFAULTS: readonly EosPillFilterItem[] = [
  { value: "all", label: "All routines" },
  { value: "finance", label: "Finance" },
  { value: "sales", label: "Sales" },
  { value: "support", label: "Support" },
  { value: "engineering", label: "Engineering" },
  { value: "hiring", label: "Hiring" },
  { value: "marketing", label: "Marketing" },
  { value: "personal", label: "Personal" },
];

export function EosPillFilters({
  items = EOS_PILL_DEFAULTS,
  value,
  defaultValue,
  onChange,
  label = "Filter routines",
  size = "lg",
  className,
  style,
}: EosPillFiltersProps) {
  const [current, setCurrent] = useControlled(value, defaultValue ?? items[0]?.value ?? "", onChange);
  const pills = useRef<(HTMLButtonElement | null)[]>([]);
  const row = useRef<HTMLDivElement>(null);
  const indicator = useRef<HTMLSpanElement>(null);
  const look = useEosTheme()?.look;
  const [fade, setFade] = useState<"none" | "start" | "end" | "both">("none");
  // With no item chosen (a value from elsewhere), the first pill takes the tab stop.
  const chosen = items.findIndex((item) => item.value === current);
  useEosIndicator({ host: row, indicator, target: () => pills.current[chosen], choice: `${chosen}:${items.length}`, opaque: true, look });

  useEffect(() => {
    const el = row.current;
    if (!el) return;
    const update = () => {
      const max = el.scrollWidth - el.clientWidth;
      const start = el.scrollLeft > 2;
      const end = el.scrollLeft < max - 2;
      setFade(max <= 2 ? "none" : start && end ? "both" : start ? "start" : "end");
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    const ro = typeof ResizeObserver === "function" ? new ResizeObserver(update) : null;
    ro?.observe(el);
    return () => {
      el.removeEventListener("scroll", update);
      ro?.disconnect();
    };
  }, []);

  const choose = (index: number) => {
    const item = items[index];
    if (!item) return;
    setCurrent(item.value);
    const pill = pills.current[index];
    pill?.focus();
    pill?.scrollIntoView?.({ block: "nearest", inline: "nearest" });
  };
  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const next = rovingIndex(event.key, index, items.length);
    if (next < 0) return;
    event.preventDefault();
    choose(next);
  };
  const s = SIZES[size];
  const vars = { "--eos-pill-h": `${s.h}px`, "--eos-pill-pad": `${s.pad}px`, "--eos-pill-font": `${s.font}px` } as CSSProperties;

  return (
    <EosScope>
      <style>{CSS}</style>
      <div ref={row} role="radiogroup" aria-label={label} className={cx("eos-pills", className)} data-fade={fade} style={{ ...vars, ...style }}>
        {items.map((item, index) => {
          const on = index === chosen;
          return (
            <button
              key={item.value}
              ref={(el) => {
                pills.current[index] = el;
              }}
              type="button"
              role="radio"
              aria-checked={on}
              tabIndex={on || (chosen < 0 && index === 0) ? 0 : -1}
              className="eos-pill"
              onClick={() => choose(index)}
              onKeyDown={(event) => onKeyDown(event, index)}
            >
              <span className="eos-pill-in">
                <span className="eos-pill-t" data-text={item.label}>
                  {item.label}
                </span>
                {item.count !== undefined && (
                  <span className="eos-pill-t eos-pill-count" data-text={item.count}>
                    {item.count}
                  </span>
                )}
              </span>
            </button>
          );
        })}
        <EosIndicator ref={indicator} />
      </div>
    </EosScope>
  );
}
